 // Get the compressed data offsets
 uint8_t* get_coffsets(blosc2_frame *frame, int32_t header_len, int64_t cbytes, int32_t *off_cbytes) {
+  int64_t offsets_pos = (int64_t)header_len + (frame->eframe ? 0 : cbytes);
+  int64_t trailer_pos = frame->len - (int64_t)frame->trailer_len;
+
+  /* The compressed offsets chunk must be wholly contained between the data
+   * area and the frame trailer.  Do these calculations in 64 bits: header_len
+   * and cbytes are read from the frame and must not be allowed to wrap. */
+  if (header_len < 0 || cbytes < 0 || frame->trailer_len > (uint64_t)frame->len ||
+      offsets_pos < header_len || offsets_pos > trailer_pos ||
+      trailer_pos - offsets_pos < BLOSC_EXTENDED_HEADER_LENGTH ||
+      trailer_pos - offsets_pos > INT32_MAX) {
+    BLOSC_TRACE_ERROR("Invalid offsets chunk boundaries in frame.");
+    return NULL;
+  }
+  int32_t available_cbytes = (int32_t)(trailer_pos - offsets_pos);
+
   if (frame->coffsets != NULL) {
+    int32_t declared_cbytes = sw32_(frame->coffsets + BLOSC2_CHUNK_CBYTES);
+    if (declared_cbytes < BLOSC_EXTENDED_HEADER_LENGTH || declared_cbytes > available_cbytes) {
+      BLOSC_TRACE_ERROR("Invalid compressed size for offsets chunk.");
+      return NULL;
+    }
     if (off_cbytes != NULL) {
-      *off_cbytes = *(int32_t *) (frame->coffsets + BLOSC2_CHUNK_CBYTES);
+      *off_cbytes = declared_cbytes;
     }
     return frame->coffsets;
   }
   if (frame->sdata != NULL) {
-    int32_t off_pos = header_len + cbytes;
-    // Check that there is enough room to read Blosc header
-    if (off_pos + BLOSC_EXTENDED_HEADER_LENGTH > frame->len) {
-      BLOSC_TRACE_ERROR("Cannot read the offsets past frame boundary.");
+    uint8_t* off_start = frame->sdata + offsets_pos;
+    int32_t declared_cbytes = sw32_(off_start + BLOSC2_CHUNK_CBYTES);
+    if (declared_cbytes < BLOSC_EXTENDED_HEADER_LENGTH || declared_cbytes > available_cbytes) {
+      BLOSC_TRACE_ERROR("Invalid compressed size for offsets chunk.");
       return NULL;
     }
     // For in-memory frames, the coffset is just one pointer away
-    uint8_t* off_start = frame->sdata + off_pos;
     if (off_cbytes != NULL) {
-      *off_cbytes = *(int32_t*) (off_start + BLOSC2_CHUNK_CBYTES);
+      *off_cbytes = declared_cbytes;
     }
     return off_start;
   }

-  int64_t trailer_offset = get_trailer_offset(frame, header_len, true);
-  int32_t coffsets_cbytes;
-  if (frame->eframe) {
-    coffsets_cbytes = (int32_t) (trailer_offset - (header_len + 0));
-  }
-  else {
-    coffsets_cbytes = (int32_t) (trailer_offset - (header_len + cbytes));
-  }
-  if (off_cbytes != NULL) {
-    *off_cbytes = coffsets_cbytes;
-  }
+  int32_t coffsets_cbytes = available_cbytes;
   FILE* fp = NULL;
   uint8_t* coffsets = malloc((size_t)coffsets_cbytes);
   if (frame->eframe) {
@@ -959,6 +968,15 @@
     free(coffsets);
     return NULL;
   }
+  int32_t declared_cbytes = sw32_(coffsets + BLOSC2_CHUNK_CBYTES);
+  if (declared_cbytes < BLOSC_EXTENDED_HEADER_LENGTH || declared_cbytes > coffsets_cbytes) {
+    BLOSC_TRACE_ERROR("Invalid compressed size for offsets chunk.");
+    free(coffsets);
+    return NULL;
+  }
+  if (off_cbytes != NULL) {
+    *off_cbytes = declared_cbytes;
+  }
   frame->coffsets = coffsets;
   return coffsets;
 }
@@ -1553,19 +1571,35 @@

 int64_t get_coffset(blosc2_frame* frame, int32_t header_len, int64_t cbytes, int32_t nchunk) {
   // Get the offset to nchunk
-  int64_t offset;
-  uint8_t *coffsets = get_coffsets(frame, header_len, cbytes, NULL);
+  int64_t offset = 0;
+  int32_t coffsets_cbytes = 0;
+  if (nchunk < 0) {
+    BLOSC_TRACE_ERROR("Negative chunk index.");
+    return -3;
+  }
+  uint8_t *coffsets = get_coffsets(frame, header_len, cbytes, &coffsets_cbytes);
   if (coffsets == NULL) {
     BLOSC_TRACE_ERROR("Cannot get the offset for chunk %d for the frame.", nchunk);
     return -3;
   }

-  // Get the 64-bit offset
-  int rc = blosc_getitem(coffsets, nchunk, 1, &offset);
-  if (rc < 0) {
+  // Get the 64-bit offset, limiting all reads to the validated offsets chunk.
+  blosc2_dparams dparams = BLOSC2_DPARAMS_DEFAULTS;
+  blosc2_context *dctx = blosc2_create_dctx(dparams);
+  if (dctx == NULL) {
+    return -4;
+  }
+  int rc = blosc2_getitem_ctx(dctx, coffsets, coffsets_cbytes, nchunk, 1, &offset);
+  blosc2_free_ctx(dctx);
+  if (rc != (int)sizeof(offset)) {
     BLOSC_TRACE_ERROR("Problems retrieving a chunk offset.");
     return -4;
   }
+  if (!frame->eframe && offset >= 0 &&
+      (cbytes < BLOSC_MIN_HEADER_LENGTH || offset > cbytes - BLOSC_MIN_HEADER_LENGTH)) {
+    BLOSC_TRACE_ERROR("Chunk offset is outside the frame data area.");
+    return -4;
+  }
   return offset;
 }

